NOTICE_PAY.conversion:
const months = calendar_completed_months(
	get(ctx.subject.employment, 'service_started_on', ctx.subject.employment.effective_range.from),
	add_days(ctx.entry.incurred_on, 1)
);
const band = ctx.lookup.service_bands.filter((row) => months >= row.months).at(-1);
const daily = Math.max(ctx.entry.quantity, ctx.day_rate);
return daily * (band == null ? 0 : band.days);

RETIREMENT_PAY.eligibility:
const birth = get(ctx.subject.employment, 'payroll.date_of_birth', null);
if (birth == null) return false;
const age = age_on(birth, ctx.entry.incurred_on);
const months = calendar_completed_months(
	get(ctx.subject.employment, 'service_started_on', ctx.subject.employment.effective_range.from),
	add_days(ctx.entry.incurred_on, 1)
);
if (ctx.entry.unit !== 'MONEY') return false;
if (!(ctx.entry.quantity > 0)) return false;
if (!(ctx.entry.incurred_on >= ctx.subject.employment.effective_range.from)) return false;
if (get(ctx.subject.employment, 'employee_extension_data.retirement_disability', false) === true) return true;
return ctx.lookup.retirement_eligibility.some((band) => {
	if (!(months >= band.months)) return false;
	return band.age == null || age >= band.age;
});

RETIREMENT_PAY.conversion:
const facts = get(ctx.subject.employment, 'employee_extension_data', {});
// 勞基法 §17, §55: a worker who kept the LSA pension, or a foreigner outside 勞工退休金條例 §7, is on the Act for the whole service.
const residency = get(ctx.subject.employment, 'terms.residency_status', 'CITIZEN');
const spouse = get(facts, 'foreign_spouse_of_national', false) === true;
const professional = ctx.lookup.foreign_professional_covered === true && get(facts, 'foreign_professional', false) === true;
const lsa = get(facts, 'statutory.LABOR_PENSION.pension_system', 'NEW') === 'LSA';
const whole = lsa || (residency === 'FOREIGNER' && !spouse && !professional);
const start = get(ctx.subject.employment, 'service_started_on', ctx.subject.employment.effective_range.from);
const recorded = get(ctx.subject.employment, 'employee_extension_data.old_system_service_months', null);
const end = whole || recorded != null || ctx.entry.incurred_on < ctx.lookup.old_system_cutoff
	? ctx.entry.incurred_on
	: add_days(ctx.lookup.old_system_cutoff, -1);
const month_days = 30;
const months = calendar_completed_months(start, add_days(end, 1));
const tail = calendar_distance_days(add_months(start, months), add_days(end, 1));
const total = months + tail / month_days;
const served = whole || recorded == null ? total : recorded;
const old = whole || recorded != null || start < ctx.lookup.old_system_cutoff ? Math.min(total, served) : 0;
const years = Math.floor(old / 12);
const remainder = old - years * 12;
const tail_years =
	remainder === 0 ? 0
	: remainder < ctx.lookup.tail_threshold_months ? ctx.lookup.short_tail_years
	: ctx.lookup.long_tail_years;
const credited = years + tail_years;
const units = Math.min(
	ctx.lookup.cap_months,
	Math.min(ctx.lookup.first_years, credited) * ctx.lookup.first_rate +
		Math.max(0, credited - ctx.lookup.first_years) * ctx.lookup.later_rate
);
const uplift = get(ctx.subject.employment, 'employee_extension_data.retirement_disability_duty_caused', false) === true
	? ctx.lookup.duty_disability_uplift
	: 1;
return ctx.entry.quantity * units * uplift;

