  ['PARENTAL_LEAVE', 'PARENTAL_LEAVE_BY_DAY'].includes(slot.code) && month_start(slot.date) === month
).length / 2;
const days = Math.max(0, last_day - first_day + 1 - parental);
return round(insured * ctx.lookup.rate * ctx.lookup.insurance_employee_share * (1 - subsidy) * days / month_days, 1, 'HALF_UP');

EI.employer_amount:
// 就業保險法 §8, §40–41: 1% of the LI grade, 70% employer, before age 65, by covered days on a 30-day month.
const employment = ctx.subject.employment;
const facts = get(employment, 'employee_extension_data', {});
const born = get(employment, 'payroll.date_of_birth', null);
const age = born == null || born === '' ? 0 : age_on(born, ctx.run.salary_coverage.to);
if (age >= ctx.lookup.maximum_coverage_age_years) return 0;
const residency = get(employment, 'terms.residency_status', 'CITIZEN');
const spouse = get(facts, 'foreign_spouse_of_national', false) === true;
const professional = ctx.lookup.foreign_professional_covered === true && get(facts, 'foreign_professional', false) === true;
const covered = residency === 'CITIZEN' || spouse || (residency === 'PERMANENT_RESIDENT' && professional);
if (!covered) return 0;
const wage = get(employment, 'terms.rate.unit', 'MONTHLY') === 'MONTHLY'
  ? round(ctx.month_wage, 0.01)
  : Math.max(0, get(ctx.subtotals, 'ORDINARY_WAGES', 0));
const grades = get(employment, 'engagement', '') === 'PART_TIME'
  ? ctx.lookup.li_part_time_grades.concat(ctx.lookup.li_grades)
  : ctx.lookup.li_grades;
const grade = grades.find((row) => row >= wage) ?? grades.at(-1);
const insured = Number(get(facts, 'statutory.LI.insured_amount', grade));
const month = month_start(ctx.as_of);
const last = month_end(ctx.as_of);
const from = get(employment, 'effective_range.from', month);
const to = get(employment, 'effective_range.to', last);
const month_days = 30;
const first_day = from > month ? Math.min(month_days, Number(from.substring(8))) : 1;
const last_day = to >= last ? month_days : Number(to.substring(8));
const parental = (ctx.leave ?? []).filter((slot) =>
  ['PARENTAL_LEAVE', 'PARENTAL_LEAVE_BY_DAY'].includes(slot.code) && month_start(slot.date) === month
).length / 2;
const days = Math.max(0, last_day - first_day + 1 - parental);
return round(insured * ctx.lookup.rate * ctx.lookup.insurance_employer_share * days / month_days, 1, 'HALF_UP');

NHI.employee_amount:
// 全民健康保險法 §18, §27, §29: 30% employee share, subsidised on the worker's own share, plus one full share for each of up to three dependants.
const employment = ctx.subject.employment;
const facts = get(employment, 'employee_extension_data', {});
if (get(facts, 'statutory.NHI.insured_elsewhere', false) === true) return 0;
const exit = get(employment, 'effective_range.to', '');
if (exit !== '' && !(exit >= ctx.run.salary_coverage.to)) return 0;
const wage = get(employment, 'terms.rate.unit', 'MONTHLY') === 'MONTHLY'
  ? round(ctx.month_wage, 0.01)
  : Math.max(0, get(ctx.subtotals, 'ORDINARY_WAGES', 0));
const grade = ctx.lookup.nhi_grades.find((row) => row >= wage) ?? ctx.lookup.nhi_grades.at(-1);
const insured = Number(get(facts, 'statutory.NHI.insured_amount', grade));
const dependants = Math.min(ctx.lookup.maximum_employee_dependants, Number(get(facts, 'statutory.NHI.enrolled_dependants', 0)));
const subsidy = Number(get(facts, 'statutory.NHI.disability_subsidy', 0)) / 100;
const own = round(insured * ctx.lookup.rate * ctx.lookup.employee_share, 1, 'HALF_UP');
return round(own * (1 - subsidy) + own * dependants, 1, 'HALF_UP');

NHI.employer_amount:
// 全民健康保險法 §18, §27: 60% employer share on the insured amount, times the announced 1.56 average dependant factor.
const employment = ctx.subject.employment;
const facts = get(employment, 'employee_extension_data', {});
if (get(facts, 'statutory.NHI.insured_elsewhere', false) === true) return 0;
const exit = get(employment, 'effective_range.to', '');
if (exit !== '' && !(exit >= ctx.run.salary_coverage.to)) return 0;
const wage = get(employment, 'terms.rate.unit', 'MONTHLY') === 'MONTHLY'
  ? round(ctx.month_wage, 0.01)
  : Math.max(0, get(ctx.subtotals, 'ORDINARY_WAGES', 0));
const grade = ctx.lookup.nhi_grades.find((row) => row >= wage) ?? ctx.lookup.nhi_grades.at(-1);
const insured = Number(get(facts, 'statutory.NHI.insured_amount', grade));
return round(insured * ctx.lookup.rate * ctx.lookup.employer_share * ctx.lookup.average_dependants, 1, 'HALF_UP');

NHI_SUPPLEMENT.employee_amount:
// 全民健康保險法 §31(1)(1); 扣取及繳納補充保險費辦法 §4, §6: 2.11% on the part of this bonus that takes the year's bonuses past four times the insured amount, at most NT$10,000,000 a payment. §9: what was over-deducted goes back, so a recovery owes what the year's bonuses leave less what they bore.
const employment = ctx.subject.employment;
const facts = get(employment, 'employee_extension_data', {});
const wage = get(employment, 'terms.rate.unit', 'MONTHLY') === 'MONTHLY'
  ? round(ctx.month_wage, 0.01)
  : Math.max(0, get(ctx.subtotals, 'ORDINARY_WAGES', 0));
const grade = ctx.lookup.nhi_grades.find((row) => row >= wage) ?? ctx.lookup.nhi_grades.at(-1);
const insured = Number(get(facts, 'statutory.NHI.insured_amount', grade));
const bonus = get(ctx.subtotals, 'ADDITIONAL_WAGES', 0) - get(ctx.subtotals, 'ORDINARY_WAGES', 0);
const paid = Number(get(ctx.balances, 'ytd.ADDITIONAL_WAGES', 0)) - Number(get(ctx.balances, 'ytd.ORDINARY_WAGES', 0));
if (bonus < 0) {
  const schemes = get(ctx.balances, 'statutory_contribution', {});
  const bore = Object.hasOwn(schemes, 'NHI_SUPPLEMENT.employee') ? Number(schemes['NHI_SUPPLEMENT.employee']) : 0;
  const left = Math.max(0, paid + bonus - ctx.lookup.bonus_salary_multiple * insured);
  return Math.min(0, round(left * ctx.lookup.nhi_supplement_rate, 1, 'HALF_UP') - bore);
}
const excess = Math.max(0, paid + bonus - ctx.lookup.bonus_salary_multiple * insured);
return round(Math.min(excess, bonus, ctx.lookup.nhi_supplement_payment_ceiling) * ctx.lookup.nhi_supplement_rate, 1, 'HALF_UP');

NHI_PART_TIME.employee_amount:
// 全民健康保險法 §31(1)(2): 2.11% on a salary payment to a worker insured elsewhere, charged whole from the minimum wage. SALARY_INCOME holds no exempt meal or §32 overtime (所得稅法 §14(1)(3)).
const facts = get(ctx.subject.employment, 'employee_extension_data', {});
if (get(facts, 'statutory.NHI.insured_elsewhere', false) !== true) return 0;
if (get(facts, 'statutory.NHI_PART_TIME.exempt', false) === true) return 0;
const payment = get(ctx.subtotals, 'SALARY_INCOME', 0);
if (!(payment >= ctx.lookup.monthly_wage)) return 0;
return round(Math.min(payment, ctx.lookup.nhi_supplement_payment_ceiling) * ctx.lookup.nhi_supplement_rate, 1, 'HALF_UP');

LABOR_PENSION.employee_amount:
// 勞工退休金條例 §14(3), §16: the worker's voluntary contribution, up to 6% of the contribution grade, by days on a 30-day month.
