const insured = Number(get(facts, 'statutory.LABOR_PENSION.insured_amount', grade));
const rate = Number(get(facts, 'statutory.LABOR_PENSION.voluntary_rate', 0)) / 100;
const month = month_start(ctx.as_of);
const last = month_end(ctx.as_of);
