  ['PARENTAL_LEAVE', 'PARENTAL_LEAVE_BY_DAY'].includes(slot.code) && month_start(slot.date) === month
).length / 2;
const days = Math.max(0, last_day - first_day + 1 - parental);
return round(insured * rate * days / month_days, 1, 'HALF_UP');

