OCC_INJURY.employer_amount:
// 勞工職業災害保險及保護法 §16–17: the insured grade times the notified experience rate, or the industry rate plus the 0.07% commuting rate, by covered days on a 30-day month.
const employment = ctx.subject.employment;
const facts = get(employment, 'employee_extension_data', {});
