const risk = get(entity, 'risk_class', null);
const industry = risk == null ? null : get(ctx.lookup.industry_rate_percent, String(risk), null);
const base = industry == null ? ctx.lookup.default_rate_percent : industry;
const rate = experience != null ? Number(experience) : base + ctx.lookup.commuting_rate_percent;
const month = month_start(ctx.as_of);
const last = month_end(ctx.as_of);
const from = get(employment, 'effective_range.from', month);
const to = get(employment, 'effective_range.to', last);
