).length / 2;
const days = Math.max(0, last_day - first_day + 1 - parental);
return round(insured * rate / 100 * days / month_days, 1, 'HALF_UP');

INCOME_TAX.employee_amount:
// 薪資所得扣繳辦法 §6–7: without a 免稅額申報表 the resident salary bears 5% of the whole month, withheld above NT$2,000; with one, annualise the month, deduct the exemptions and the standard and salary deductions, apply the 所得稅法 §5 ladder and withhold a twelfth. A 兼職所得 salary bears 5% from the 起扣標準. SALARY_INCOME holds no exempt meal or §32 overtime (所得稅法 §14(1)(3); 財政部台財稅第16713號).
const facts = get(ctx.subject.employment, 'employee_extension_data', {});
const elections = get(facts, 'statutory.INCOME_TAX', {});
const payDate = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.to));
const year = payDate.substring(0, 4);
const review = get(elections, 'tax_residency_reviews.' + year, null);
const person = get(ctx.subject, 'employee.name', 'this worker');
if (review == null) {
  if (!(get(ctx.subtotals, 'FINAL_PAY', 0) > 0)) return 0;
  throw 'Record the ' + year + ' tax residency review of ' + person + ' before paying.';
}
if (payDate > get(review, 'valid_through', payDate)) throw 'The ' + year + ' tax residency review of ' + person + ' ended before this pay date.';
if (get(review, 'reconciliation_required', false) === true) throw 'Complete the tax reconciliation of ' + person + ' offline before paying.';
const residentFrom = get(review, 'resident_from', null);
if (residentFrom === null || residentFrom > payDate) return 0;
const payment = Math.max(0, get(ctx.subtotals, 'SALARY_INCOME', 0) - Number(get(ctx.statutory, 'LABOR_PENSION.employee', 0)));
// §7: 兼職所得 is judged by each payment, 每次給付金額
if (get(elections, 'part_time_income', false) === true) {
  if (payment < ctx.lookup.bonus_withholding_threshold) return 0;
  return round(payment * ctx.lookup.withholding_rate, 1, 'DOWN');
}
// §6: a monthly salary bears tax on 全月給付總額: what an earlier run of this month paid is in the balance.
const month = get(ctx, 'balances.month', {});
const paidMonth = payDate.slice(0, 7);
const heldIn = (code) => (Object.hasOwn(month, paidMonth + '.' + code) ? Number(month[paidMonth + '.' + code]) : 0);
const coverage = ctx.run.salary_coverage;
const wholeMonth =
	String(coverage.from) === String(month_start(coverage.from)) && String(coverage.to) === String(month_end(coverage.from));
const separate = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn('BASIC') > 0;
const before = (code) => (separate ? 0 : heldIn(code));
const wage = Math.max(0, payment + before('SALARY_INCOME') - before('LABOR_PENSION.employee'));
const exemptions = get(elections, 'exemptions', null);
if (exemptions == null) {
  const flat = round(wage * ctx.lookup.withholding_rate, 1, 'DOWN');
  return (flat > ctx.lookup.minimum_withholding ? flat : 0) - before('INCOME_TAX.employee');
}
const dependants = Math.max(0, Number(exemptions));
const table = wage <= ctx.lookup.monthly_salary_rounding_threshold && dependants <= ctx.lookup.table_maximum_dependants;
const stepped = table ? round(wage, ctx.lookup.monthly_salary_rounding_step, 'UP') - ctx.lookup.monthly_salary_rounding_step : wage;
const annual = 12 * stepped;
const deduction = ctx.lookup.annual_exemption_per_person * (1 + dependants)
  + ctx.lookup.annual_standard_deduction
  + Math.min(ctx.lookup.annual_salary_deduction, annual);
const yearly = ladder(Math.max(0, annual - deduction), ctx.lookup.bands);
const tax = round(yearly / 12, table ? ctx.lookup.monthly_tax_step : 1, 'DOWN');
return (tax > ctx.lookup.minimum_withholding ? tax : 0) - before('INCOME_TAX.employee');

INCOME_TAX_NON_RESIDENT.employee_amount:
// 各類所得扣繳率標準 §3: 18% of the non-resident's whole salary, or 6% where 全月薪資給付總額 is at or below 1.5 times the minimum wage, truncated. SALARY_INCOME holds no exempt meal or §32 overtime (所得稅法 §14(1)(3)).
const facts = get(ctx.subject.employment, 'employee_extension_data', {});
const payDate = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.to));
const review = get(facts, 'statutory.INCOME_TAX.tax_residency_reviews.' + payDate.substring(0, 4), null);
const residentFrom = get(review, 'resident_from', null);
if (review == null) return 0;
if (residentFrom !== null && residentFrom <= payDate) return 0;
const bonus = get(ctx.subtotals, 'ADDITIONAL_WAGES', 0) - get(ctx.subtotals, 'ORDINARY_WAGES', 0);
// The band reads the month's salary: what an earlier run of this month paid is in the balance.
const month = get(ctx, 'balances.month', {});
const paidMonth = payDate.slice(0, 7);
const heldIn = (code) => (Object.hasOwn(month, paidMonth + '.' + code) ? Number(month[paidMonth + '.' + code]) : 0);
const coverage = ctx.run.salary_coverage;
const wholeMonth =
	String(coverage.from) === String(month_start(coverage.from)) && String(coverage.to) === String(month_end(coverage.from));
const separate = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn('BASIC') > 0;
const before = (code) => (separate ? 0 : heldIn(code));
const wage = Math.max(
	0,
	get(ctx.subtotals, 'SALARY_INCOME', 0) + bonus + before('SALARY_INCOME') + before('ADDITIONAL_WAGES') - before('ORDINARY_WAGES')
);
const low = wage <= ctx.lookup.lower_rate_wage_multiple * ctx.lookup.monthly_wage;
return round(wage * (low ? ctx.lookup.lower_rate : ctx.lookup.non_resident_rate), 1, 'DOWN') - before('INCOME_TAX_NON_RESIDENT.employee');

LABOR_PENSION_RESERVE.employer_amount:
// 勞動基準法 §56(1): 2%–15% of the wages of the workers still on the old pension system, at the rate the entity declares.
const facts = get(ctx.subject.employment, 'employee_extension_data', {});
const entity = get(ctx.subject.employer, 'entity_extension_data', {});
const wage = Math.max(0, get(ctx.subtotals, 'ORDINARY_WAGES', 0));
const pension = get(facts, 'statutory.LABOR_PENSION.pension_system', 'NEW');
const residency = get(ctx.subject.employment, 'terms.residency_status', 'CITIZEN');
const professional = ctx.lookup.foreign_professional_covered === true && get(facts, 'foreign_professional', false) === true;
const spouse = get(facts, 'foreign_spouse_of_national', false) === true;
const covered = residency !== 'FOREIGNER' || professional || spouse;
if (pension !== 'LSA' && covered) return 0;
const declared = get(entity, 'pension_reserve_rate', null);
if (declared == null) throw 'Record the entity pension_reserve_rate: ' + get(ctx.subject, 'employee.name', 'a worker') + ' is on the LSA pension.';
return round(wage * Number(declared) / 100, 1, 'HALF_UP');

INCOME_TAX_BONUS.employee_amount:
// 薪資所得扣繳辦法 §6–7: 5% on each non-monthly bonus payment at or above the 起扣標準, truncated. A recovery takes back what the bonus it corrects bore.
const facts = get(ctx.subject.employment, 'employee_extension_data', {});
const payDate = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.to));
const review = get(facts, 'statutory.INCOME_TAX.tax_residency_reviews.' + payDate.substring(0, 4), null);
const residentFrom = get(review, 'resident_from', null);
if (residentFrom === null || residentFrom > payDate) return 0;
const bonus = get(ctx.subtotals, 'ADDITIONAL_WAGES', 0) - get(ctx.subtotals, 'ORDINARY_WAGES', 0);
if (bonus < 0) {
  const schemes = get(ctx.balances, 'statutory_contribution', {});
  const withheld = Object.hasOwn(schemes, 'INCOME_TAX_BONUS.employee') ? Number(schemes['INCOME_TAX_BONUS.employee']) : 0;
  return -Math.min(withheld, round(-bonus * ctx.lookup.withholding_rate, 1, 'DOWN'));
}
if (bonus < ctx.lookup.bonus_withholding_threshold) return 0;
return round(bonus * ctx.lookup.withholding_rate, 1, 'DOWN');

SEVERANCE_TAX.employee_amount:
// 所得稅法 §14(1)(9) with 各類所得扣繳率標準 §2: 6% withheld on the exit pay above the per-service-year exemption, truncated; a tail under six months counts as half a year.
// the exemption is on the whole exit pay: a further payment or a recovery owes what the year's total leaves
const now = get(ctx.subtotals, 'RETIREMENT', 0) - get(ctx.subtotals, 'ADDITIONAL_WAGES', 0);
if (now === 0) return 0;
const pay = Math.max(0, now + Number(get(ctx.balances, 'ytd.RETIREMENT', 0)) - Number(get(ctx.balances, 'ytd.ADDITIONAL_WAGES', 0)));
const facts = get(ctx.subject.employment, 'employee_extension_data', {});
const payDate = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.to));
const review = get(facts, 'statutory.INCOME_TAX.tax_residency_reviews.' + payDate.substring(0, 4), null);
const residentFrom = get(review, 'resident_from', null);
if (residentFrom === null || residentFrom > payDate) return 0;
const start = get(ctx.subject.employment, 'service_started_on', get(ctx.subject.employment, 'effective_range.from', ctx.run.salary_coverage.from));
const end = add_days(get(ctx.subject.employment, 'effective_range.to', payDate), 1);
const months = calendar_completed_months(start, end);
const tail = months % 12;
const part = tail > 0 || add_months(start, months) < end;
const tail_years =
  tail >= ctx.lookup.tail_threshold_months ? ctx.lookup.long_tail_years
  : part ? ctx.lookup.short_tail_years
  : 0;
const years = Math.floor(months / 12) + tail_years;
const exempt = ctx.lookup.retirement_exemption_per_service_year * years;
const schemes = get(ctx.balances, 'statutory_contribution', {});
const withheld = Object.hasOwn(schemes, 'SEVERANCE_TAX.employee') ? Number(schemes['SEVERANCE_TAX.employee']) : 0;
return round(Math.max(0, pay - exempt) * ctx.lookup.rate, 1, 'DOWN') - withheld;

WELFARE_FUND.employee_amount:
// 職工福利金條例 §2(1)(3): 0.5% of the wage, deducted from the worker, where the entity has a welfare committee.
const entity = get(ctx.subject.employer, 'entity_extension_data', {});
const wage = Math.max(0, get(ctx.subtotals, 'ORDINARY_WAGES', 0));
return get(entity, 'welfare_committee_established', false) === true ? round(wage * ctx.lookup.employee_rate, 1, 'HALF_UP') : 0;

SEVERANCE_TAX_NON_RESIDENT.employee_amount:
// 所得稅法 §14(1)(9) with 各類所得扣繳率標準 §2: 18% withheld on the exit pay above the per-service-year exemption, truncated; a tail under six months counts as half a year.
// the exemption is on the whole exit pay: a further payment or a recovery owes what the year's total leaves
const now = get(ctx.subtotals, 'RETIREMENT', 0) - get(ctx.subtotals, 'ADDITIONAL_WAGES', 0);
if (now === 0) return 0;
const pay = Math.max(0, now + Number(get(ctx.balances, 'ytd.RETIREMENT', 0)) - Number(get(ctx.balances, 'ytd.ADDITIONAL_WAGES', 0)));
const facts = get(ctx.subject.employment, 'employee_extension_data', {});
const payDate = String(get(ctx.run, 'pay_date', ctx.run.salary_coverage.to));
const review = get(facts, 'statutory.INCOME_TAX.tax_residency_reviews.' + payDate.substring(0, 4), null);
const residentFrom = get(review, 'resident_from', null);
if (residentFrom !== null && residentFrom <= payDate) return 0;
const start = get(ctx.subject.employment, 'service_started_on', get(ctx.subject.employment, 'effective_range.from', ctx.run.salary_coverage.from));
const end = add_days(get(ctx.subject.employment, 'effective_range.to', payDate), 1);
const months = calendar_completed_months(start, end);
const tail = months % 12;
const part = tail > 0 || add_months(start, months) < end;
const tail_years =
  tail >= ctx.lookup.tail_threshold_months ? ctx.lookup.long_tail_years
  : part ? ctx.lookup.short_tail_years
  : 0;
const years = Math.floor(months / 12) + tail_years;
const exempt = ctx.lookup.retirement_exemption_per_service_year * years;
const schemes = get(ctx.balances, 'statutory_contribution', {});
const withheld = Object.hasOwn(schemes, 'SEVERANCE_TAX_NON_RESIDENT.employee') ? Number(schemes['SEVERANCE_TAX_NON_RESIDENT.employee']) : 0;
return round(Math.max(0, pay - exempt) * ctx.lookup.non_resident_rate, 1, 'DOWN') - withheld;

