NHI_EMPLOYER_SUPPLEMENTARY_PREMIUM.effects:
// 全民健康保險法 §34; NHIA: (單位薪資總額 − 受僱者投保金額總額) × 2.11%, netted across the unit for the payment month. A second run in the month owes only the step it adds.
const key = 'NHI_EMPLOYER_SUPPLEMENTARY_PREMIUM:' + ctx.entry.id;
if (ctx.reads.obligation.some((task) => task.occurrence_key === key)) return [];
const income = (slip) => {
	const at = (code) => get(get(slip, 'breakdown.checkpoints', []).find((row) => row.code === code), 'value', 0);
	return Math.max(0, at('SALARY_INCOME') + at('ADDITIONAL_WAGES') - at('ORDINARY_WAGES'));
};
const total = sum(ctx.reads.payslip.map(income));
const own = sum(ctx.reads.payslip.filter((slip) => slip.payroll_run_id === ctx.entry.id).map(income));
const month = ctx.entry.pay_date.substring(0, 7);
const insured = get(ctx.subject.employer, 'entity_extension_data.nhi_month_insured_totals.' + month + '.amount', null);
const task = (title) => [{
	entity_id: ctx.entry.entity_id,
	title: title,
	due_on: month_end(add_months(ctx.entry.pay_date, 1)),
	occurrence_key: key
}];
if (insured == null) return task('NHI employer supplementary premium (§34): record the reviewed insured total for ' + month);
const premium = (paid) => round(Math.max(0, paid - insured) * ctx.lookup.nhi_supplement_rate, 1, 'HALF_UP');
const amount = premium(total) - premium(total - own);
if (!(amount > 0)) return [];
return task('NHI employer supplementary premium (§34): NT$' + amount.toFixed(0));

