MASS_LAYOFF_PLAN.effects:
const exit = ctx.entry.effective_range.to;
const notice = add_days(exit, -ctx.lookup.advance_notice_days);
const windowFrom = add_days(exit, -ctx.lookup.window_days);
const employments = ['EMPLOYEE', 'PART_TIME', 'INTERN', 'APPRENTICE'];
const counted = ctx.reads.employee_contract.filter((row) => {
	if (row.status !== 'SEALED') return false;
	if (!employments.includes(row.engagement)) return false;
	if (get(row, 'employee_extension_data.fixed_term_category', null) == null) return true;
	return !(get(row, 'employee_extension_data.migrant_worker', false) === true || get(row, 'employee_extension_data.foreign_professional', false) === true);
});
const leaverAt = (row) => {
	if (!ctx.lookup.grounds.includes(get(row, 'employee_extension_data.lsa_termination_ground', 'OTHER'))) return false;
	const to = row.effective_range.to;
	return to != null && to >= windowFrom && to <= exit;
};
const activeAt = (row) =>
	row.effective_range.from <= exit && (row.effective_range.to == null || row.effective_range.to >= exit);
const rollingOf = (count) =>
	count < ctx.lookup.small_site_upper ? ctx.lookup.small_site_count
	: count < ctx.lookup.medium_site_upper ? Math.floor(count / ctx.lookup.medium_site_divisor)
	: count < ctx.lookup.large_site_upper ? Math.floor(count / ctx.lookup.large_site_divisor)
	: Math.floor(count / ctx.lookup.largest_site_divisor);
const dailyOf = (count) =>
	count < ctx.lookup.medium_site_upper ? ctx.lookup.medium_site_daily
	: count < ctx.lookup.large_site_upper ? ctx.lookup.large_site_daily
	: ctx.lookup.largest_site_daily;
const bySite = group_by(counted, 'terms.worksite');
const raised = (ctx.reads.obligation ?? []).map((task) => String(task.occurrence_key));
return Object.entries(bySite).flatMap(([site, list]) => {
	if (site === '') return [];
	const staff = list.filter(activeAt);
	const leavers = list.filter(leaverAt);
	const count = staff.length;
	const day = leavers.filter((row) => row.effective_range.to === exit).length;
	if (!(leavers.length > rollingOf(count) || (count >= ctx.lookup.small_site_upper && day > dailyOf(count)))) return [];
	const key = 'MASS_LAYOFF_PLAN:' + ctx.entry.entity_id + ':' + site + ':' + notice;
	return raised.includes(key) ? [] : [{
		entity_id: ctx.entry.entity_id,
		employment_id: ctx.entry.id,
		title: 'Mass layoff plan for ' + site + ' notified sixty days before',
		due_on: notice,
		occurrence_key: key
	}];
});

