MINIMUM_WAGE_FLOOR.validate:
// 最低工資法 §5: an agreed monthly wage may not fall below the minimum wage.
// A part-time worker is held to the hourly floor; sheltered employment to its assessed wage.
const rate = get(ctx.entry, 'terms.rate', null);
if (rate == null || get(rate, 'unit', null) !== 'MONTHLY') return true;
if (get(ctx.entry, 'engagement', null) === 'PART_TIME') return true;
const worker = get(ctx.entry, 'employee_extension_data.worker_category', null);
if (worker === 'SHELTERED_EMPLOYMENT') return true;
// LSA §3 excludes household domestic workers from the general floor; their own rule decides
if (['DOMESTIC_CAREGIVER', 'DOMESTIC_HELPER'].includes(worker)) return true;
const allowances = Object.values(get(ctx.entry, 'terms.allowances', {})).reduce((total, allowance) => total + Number(get(allowance, 'amount', 0)), 0);
return Number(get(rate, 'amount', 0)) + allowances >= ctx.lookup.monthly_wage;

OVERTIME_DAILY_CAP.validate:
// 勞動基準法 §32(2): the day's work, overtime included, may not exceed twelve hours.
const lifted = get(ctx.subject.employer, 'entity_extension_data.responsibility_system', false) === true
  && get(ctx.subject.employment, 'employee_extension_data.responsibility_system_agreement', '') !== '';
if (lifted) return true;
return interval_minutes(get(ctx.entry, 'actual_worked_intervals', [])) <= ctx.lookup.daily_limit_minutes;

MINIMUM_WAGE_HOURLY.validate:
// 最低工資法 §5: an agreed hourly wage may not fall below the hourly minimum wage.
const rate = get(ctx.entry, 'terms.rate', null);
if (rate == null) return true;
const unit = get(rate, 'unit', null);
if (unit !== 'HOURLY' && unit !== 'DAILY') return true;
const worker = get(ctx.entry, 'employee_extension_data.worker_category', null);
if (worker === 'SHELTERED_EMPLOYMENT') return true;
if (['DOMESTIC_CAREGIVER', 'DOMESTIC_HELPER'].includes(worker)) return true;
const hours = unit === 'DAILY' ? Number(get(ctx.entry, 'terms.normal_hours_per_day', 8)) : 1;
return get(rate, 'amount', 0) >= ctx.lookup.hourly_wage * hours;

UNDER_FIFTEEN_EMPLOYMENT.validate:
// 勞動基準法 §45(1): a worker under fifteen needs the recorded exception.
const born = get(ctx.entry, 'payroll.date_of_birth', null);
const from = get(ctx.entry, 'effective_range.from', null);
if (born == null || from == null) return true;
if (age_on(born, from) >= ctx.lookup.minimum_age) return true;
const reference = get(ctx.entry, 'employee_extension_data.under_15_exception_reference', null);
return typeof reference === 'string' && reference !== '';

CHILD_WORKER_LIMITS.validate:
// 勞動基準法 §44(1), §47–48: a child worker's normal hours are eight a day, forty a week.
const born = get(ctx.entry, 'payroll.date_of_birth', null);
const from = get(ctx.entry, 'effective_range.from', null);
if (born == null || from == null) return true;
if (age_on(born, from) >= ctx.lookup.maximum_age) return true;
const day = get(ctx.entry, 'terms.normal_hours_per_day', 0);
const week = get(ctx.entry, 'terms.normal_hours_per_week', 0);
return !(day > 8 || week > ctx.lookup.weekly_hours);

BREAK_AFTER_FOUR_HOURS.validate:
// 勞動基準法 §35: four hours of continuous work need thirty continuous minutes of rest.
// A day of one work span is checked; split shifts are the run's aggregate.
if (get(ctx.subject.employer, 'entity_extension_data.shift_or_continuous_work', false) === true) return true;
const worked = get(ctx.entry, 'actual_worked_intervals', []);
if (worked.length !== 1) return true;
const row = first(worked);
const end = get(row, 'end', null);
if (end == null) return true;
if (elapsed_minutes(get(row, 'start', null), end) <= ctx.lookup.break_after_minutes) return true;
return interval_minutes(get(row, 'breaks', [])) >= ctx.lookup.break_minutes;

NORMAL_HOURS.validate:
// 勞動基準法 §30(1): normal time is eight hours a day; the weekly forty is the run's aggregate.
const lifted = get(ctx.subject.employer, 'entity_extension_data.responsibility_system', false) === true
  && get(ctx.subject.employment, 'employee_extension_data.responsibility_system_agreement', '') !== '';
if (lifted) return true;
if (get(ctx.subject.employer, 'entity_extension_data.flexible_working_time', false) === true) return true;
const worked = interval_minutes(get(ctx.entry, 'actual_worked_intervals', []));
const overtime = interval_minutes(get(ctx.entry, 'planned_overtime_intervals', []));
return worked - overtime <= ctx.lookup.normal_minutes_per_day;

DOMESTIC_MIGRANT_WAGE.validate:
// 勞動基準法 §3 excludes household domestic workers from the Act; the Ministry of Labour
// set NT$20,000 for new and renewed contracts from 2022-08-10.
const worker = get(ctx.entry, 'employee_extension_data.worker_category', null);
if (!['DOMESTIC_CAREGIVER', 'DOMESTIC_HELPER'].includes(worker)) return true;
if (get(ctx.entry, 'engagement', 'EMPLOYEE') !== 'EMPLOYEE') return true;
const rate = get(ctx.entry, 'terms.rate', null);
if (rate == null) return false;
if (get(rate, 'unit', null) !== 'MONTHLY') return true;
if (String(ctx.entry.effective_range.from) < ctx.lookup.regime_from) return true;
const amount = get(rate, 'amount', null);
return amount != null && amount >= ctx.lookup.monthly_wage;

ROSTER_DAILY_HOURS_CAP.validate:
// 勞動基準法 §32(2): planned overtime may not push the day past twelve hours.
const lifted = get(ctx.subject.employer, 'entity_extension_data.responsibility_system', false) === true
  && get(ctx.subject.employment, 'employee_extension_data.responsibility_system_agreement', '') !== '';
if (lifted) return true;
const limit = ctx.lookup.daily_limit_minutes - ctx.lookup.normal_minutes_per_day;
return interval_minutes(get(ctx.entry, 'planned_overtime_intervals', [])) <= limit;

ROSTER_BREAK_AFTER_FOUR_HOURS.validate:
// 勞動基準法 §35: planned overtime beyond four continuous hours needs its thirty-minute break.
if (get(ctx.subject.employer, 'entity_extension_data.shift_or_continuous_work', false) === true) return true;
const planned = get(ctx.entry, 'planned_overtime_intervals', []);
if (planned.length !== 1) return true;
const row = first(planned);
const end = get(row, 'end', null);
if (end == null) return true;
if (elapsed_minutes(get(row, 'start', null), end) <= ctx.lookup.break_after_minutes) return true;
return interval_minutes(get(row, 'breaks', [])) >= ctx.lookup.break_minutes;

ROSTER_ATTENDANCE_TO_THE_MINUTE.validate:
// 勞動基準法 §30(5)–(6): the attendance record shows the day to the minute.
// Planned overtime on a day with no recorded clock intervals is not a record.
if (get(ctx.entry, 'planned_overtime_intervals', []).length === 0) return true;
return get(ctx.entry, 'actual_worked_intervals', []).length > 0;

SHELTERED_EMPLOYMENT_EVIDENCE.validate:
// Disability Rights Act §40(2), §41(1), §42: a sheltered wage needs its assessment,
// signed agreement and local-authority filing on or before the governed day.
if (get(ctx.entry, 'employee_extension_data.worker_category', null) !== 'SHELTERED_EMPLOYMENT') return true;
const value = (key) => get(ctx.entry, 'employee_extension_data.' + key, null);
return ['sheltered_assessment_reference', 'sheltered_wage_agreement_reference', 'sheltered_wage_filing_reference', 'sheltered_wage_filed_on'].every((key) => typeof value(key) === 'string' && value(key) !== '');

CONTRACT_CATEGORIES.validate:
// The jurisdiction admits only these contract categories.
const categories = ctx.lookup.categories;
const category = get(ctx.entry, 'terms.statutory_work_category', null);
if (category != null && !categories.statutory_work_category.includes(category)) return false;
const residency = get(ctx.entry, 'terms.residency_status', null);
if (residency != null && !categories.residency_status.includes(residency)) return false;
return true;

SICK_LEAVE_PAY_POOL.validate:
// 勞工請假規則 §4(1), (3): half wages for thirty sick days a calendar year, hospitalised days and menstrual days past three included.
// 性別平等工作法 §14: one menstrual day a calendar month. The days beyond are SICK_LEAVE_UNPAID and MENSTRUAL_LEAVE_UNPAID.
const self = get(ctx.entry, 'id', null);
const written = get(ctx.entry, 'leave_catalog_entry_day', []);
const own = (Array.isArray(written) ? written : []).map((slot) => ({ incurred_on: String(slot.incurred_on), part: slot.part }));
const grouped = group_by(ctx.reads.leave_catalog_entry_day, 'leave_entry_id');
const slotsOf = (row) => row === ctx.entry && own.length > 0 ? own : (get(grouped, String(row.id), []) ?? []);
const rows = ctx.reads.leave_catalog_entry
  .filter((row) => row.id !== self)
  .concat([ctx.entry]);
const taken = (names, prefix) => sum(
  rows
    .filter((row) => names.includes(row.catalog_code))
    .map((row) => {
      const held = slotsOf(row).filter((slot) => String(slot.incurred_on).startsWith(prefix)).length / 2;
      return held;
    })
);
// 勞工請假規則 §4(2): hospitalised sick leave totals at most one year within any two years, its unpaid days included.
if (own.length > 0 && ctx.lookup.hospital_codes.includes(ctx.entry.catalog_code)) {
  const last = own.map((slot) => String(slot.incurred_on)).toSorted().at(-1);
  const since = String(add_months(last, -24));
  const spell = sum(
    rows
      .filter((row) => ctx.lookup.hospital_codes.includes(row.catalog_code))
      .map((row) => {
        const held = slotsOf(row).filter((slot) => String(slot.incurred_on) > since && String(slot.incurred_on) <= last).length / 2;
        return held;
      })
  );
  if (spell > ctx.lookup.hospital_pool_days)
    throw 'Hospitalised sick leave would pass the ' + ctx.lookup.hospital_pool_days + ' days allowed within two years.';
}
const months = own
  .map((slot) => String(slot.incurred_on).substring(0, 7))
  .filter((month, index, all) => all.indexOf(month) === index);
return months.every((month) => {
  if (taken(['MENSTRUAL_LEAVE', 'MENSTRUAL_LEAVE_UNPAID'], month) > ctx.lookup.menstrual_days_per_month) return false;
  const year = month.substring(0, 4);
  const menstrual = Math.max(0, taken(['MENSTRUAL_LEAVE'], year) - ctx.lookup.menstrual_free_days);
  return taken(['SICK_LEAVE', 'HOSPITALISED_SICK_LEAVE'], year) + menstrual <= ctx.lookup.sick_pool_days;
});

MARRIAGE_LEAVE_DAYS.validate:
// 勞工請假規則 §2: 結婚者給予婚假; the days of the version the leave falls in.
const slots = get(ctx.entry, 'leave_catalog_entry_day', []);
return (Array.isArray(slots) ? slots.length : 0) / 2 <= ctx.lookup.days;

MASS_LAYOFF_WORKSITE_REQUIRED.validate:
// 大量解僱勞工保護法 §2: the first four thresholds are per 廠場. Every employment contract in a
// site-counted engagement must name its establishment; a contractor, consultant or payee is not counted.
const engagement = get(ctx.entry, 'engagement', 'EMPLOYEE');
if (!['EMPLOYEE', 'PART_TIME', 'INTERN', 'APPRENTICE'].includes(engagement)) return true;
return String(get(ctx.entry, 'terms.worksite', '')).trim() !== '';

BUSINESS_EXPENSE_REIMBURSEMENT.eligibility:
if (ctx.entry.unit !== 'MONEY') return false;
if (!(ctx.entry.quantity > 0)) return false;
if (!(ctx.entry.incurred_on >= ctx.run.salary_coverage.from)) return false;
return ctx.entry.incurred_on <= ctx.run.salary_coverage.to;

ANNUAL_LEAVE.payout:
// 勞動基準法 §38(4); 施行細則 §24-1(2)(1): each unused day is paid at one day's wage. For a monthly wage, that day is
// the last month's normal working-time wage ÷ 30; ctx.day_rate is that statutory day (TW day = FIXED 30), and it
// includes the fixed allowances the contract counts in the rate.
return ctx.day_rate * ctx.entry.quantity;

MATERNITY_LEAVE.paid_share:
// 勞動基準法 §50(2): full wages after six months' service, half before.
const earliest = ctx.entry.days.map((slot) => slot.date).toSorted()[0];
return calendar_completed_months(get(ctx.subject.employment, 'service_started_on', ctx.subject.employment.effective_range.from), earliest) >= ctx.lookup.full_pay_service_months ? 1 : ctx.lookup.half_pay_share;

FOREIGN_PROFESSIONAL_PENSION_AND_EMPLOYM.effects:
const key = 'FOREIGN_PROFESSIONAL_PENSION_AND_EMPLOYMENT_INSURANCE:' + ctx.entry.id;
const raised = ctx.reads.obligation.some((task) => task.occurrence_key === key);
return raised ? [] : [{
	entity_id: ctx.entry.entity_id,
	title: 'Foreign professional pension election and registration',
	due_on: month_end(ctx.entry.salary_coverage.from),
	occurrence_key: key
}];

LABOR_PENSION_RESERVE.employer_amount:
// 勞動基準法 §56(1): 2%–15% of the wages of the workers still on the old pension system, at the rate the entity declares.
const facts = get(ctx.subject.employment, 'employee_extension_data', {});
const entity = get(ctx.subject.employer, 'entity_extension_data', {});
const wage = Math.max(0, get(ctx.subtotals, 'ORDINARY_WAGES', 0));
const pension = get(facts, 'statutory.LABOR_PENSION.pension_system', 'NEW');
const residency = get(ctx.subject.employment, 'terms.residency_status', 'CITIZEN');
// 勞動部 114年10月14日勞動福3字第1140153402A號令: from 2026-04-01 a 就業服務法 §46(1)(8)–(10) worker under ten years at the unit may leave the wage total.
const excludable = get(entity, 'pension_reserve_excludes_short_service_migrants', false) === true && get(facts, 'migrant_worker', false) === true;
if (excludable && calendar_completed_months(get(ctx.subject.employment, 'service_started_on', ctx.subject.employment.effective_range.from), add_days(ctx.run.salary_coverage.to, 1)) < 120) return 0;
const professional = ctx.lookup.foreign_professional_covered === true && get(facts, 'foreign_professional', false) === true;
const spouse = get(facts, 'foreign_spouse_of_national', false) === true;
const covered = residency !== 'FOREIGNER' || professional || spouse;
if (pension !== 'LSA' && covered) return 0;
const declared = get(entity, 'pension_reserve_rate', null);
if (declared == null) throw 'Record the entity pension_reserve_rate: ' + get(ctx.subject, 'employee.name', 'a worker') + ' is on the LSA pension.';
return round(wage * Number(declared) / 100, 1, 'HALF_UP');
